insert into public.kb_chunks (document_id, ordinal, heading, body, tokens)
select d.id, v.ordinal, v.heading, v.body, v.tokens from public.kb_documents d, public.orgs o,
(values
  (0, 'Who qualifies for Equity Uprise', 'To qualify: the website is one we built, your traffic runs through it, and payments run on the rails we connect. That is what makes the revenue countable, and the whole arrangement is priced off a count.', 51),
  (1, 'Who qualifies for Equity Uprise — What you need, and why', '- The website has to be one we built. The revenue share is calculated from what the site brings in. On a site somebody else built and hosts, we cannot see the orders, cannot verify a total, and would be asking the customer to self-report the number their own bill is based on. That is not a term either side should accept.
- The connected traffic has to run through that website. A link in a bio that goes straight to a third-party checkout is a sale the site never sees. The share is on CONNECTED revenue, and traffic routed around the site is revenue nobody can connect - which ends in an argument about a number instead of a business getting built.
- Payments have to run on the rails we connect for you. This is the meter. It is what turns ''eligible connected revenue'' from a phrase in an agreement into a figure both sides can read off the same screen on the same day.', 219),
  (2, 'Who qualifies for Equity Uprise — If that is not you', 'A business that wants to keep its existing site, or send its buyers somewhere else to pay, can still work with us - at the standard price, with no revenue share and nothing to measure. That is M Mode, and it is not a lesser door.', 58),
  (3, 'Who qualifies for Equity Uprise — What the discount is', 'Half the standard monthly price — $437.50 a month on Anti-Social instead of $875, against a capped share of the revenue the work brings in.
It is a payment arrangement. No ownership changes hands.', 49),
  (4, 'Who qualifies for Equity Uprise — It is not automatic', 'Meeting the three requirements makes somebody ELIGIBLE. It still takes a programme-fit review and a signed agreement, and it is never preselected for anybody. Do not tell somebody they are approved.', 50)
) as v(ordinal, heading, body, tokens)
 where d.org_id = o.id and o.slug = 'mccluster'
   and d.kind = 'program' and coalesce(d.url, d.title) = 'https://matthew.mccluster.org/sites-details.html#equity-eligibility';

